"""Independent replay identity and frozen-model numerical score review."""
import hashlib,json
from pathlib import Path
import numpy as np
from scipy.special import expit
H=Path(__file__).resolve().parent;E=H.parent/'exp2';P=E/'runs/fresh_behavior_final_v1'
def main():
 jobs=json.loads((E/'executions/early_batch_diagnostic_v1/jobs.json').read_text());saved={r['id']:r for r in json.loads((E/'runs/layout_monitor_transfer_v1/scores.json').read_text())};original={r['id']:r for r in map(json.loads,(H.parent/'exp6/runs/pilot_v1/raw.jsonl').open())};model=P/'models/final28_observed_violation.npz';z=np.load(model);threshold=json.loads((P/'thresholds.json').read_text())['final28_observed_violation'];checks={'positive_class_fixed':z['classes'].tolist()==[False,True]};identity=tokens=scorematch=flags=jobcoverage=True;deltas=[];allids=[];selected=set()
 def score(r):
  x=np.asarray(r['activations']['28'],dtype=np.float32);assert x.shape==(5120,) and np.isfinite(x).all();x-=z['mean'];x/=z['scale'];return float(expit(x@z['coef'].T+z['intercept'])[0])
 for job in jobs:
  raw={r['id']:r for r in map(json.loads,(E/'runs/early_batch_diagnostic_v1'/(job['name']+'.jsonl')).open())};jobcoverage &= len(raw)==len(job['requests'])==len(job['source_ids'])
  for source,q in zip(job['source_ids'],job['requests']):
   before=original[source];after=raw[q['id']];s=saved[q['id']];allids.append(q['id']);selected.add(source);identity &= before['rendered_prompt']==after['rendered_prompt'] and before['prompt_sha256']==after['prompt_sha256'] and before['unpadded_input_ids']==after['unpadded_input_ids'];tokens &= before['raw']==after['raw'] and before['generated_token_ids']==after['generated_token_ids'];a=score(before);b=score(after);scorematch &= abs(a-s['original_score'])<1e-12 and abs(b-s['repeat_score'])<1e-12 and abs((b-a)-s['delta'])<1e-12;flags &= s['original_flag']==(a>threshold) and s['repeat_flag']==(b>threshold) and s['threshold_flip']==((a>threshold)!=(b>threshold));deltas.append(b-a)
 checks.update({'132_unique_repeats_complete':len(allids)==len(set(allids))==len(saved)==132 and set(allids)==set(saved),'96_distinct_source_prompts':len(selected)==96,'all_frozen_job_links':bool(jobcoverage),'exact_actual_prompt_identity':bool(identity),'exact_generated_tokens':bool(tokens),'all_independent_scores_match':bool(scorematch),'all_fixed_threshold_flags_match':bool(flags)});a=json.loads((E/'runs/layout_monitor_transfer_v1/analysis.json').read_text());maxdelta=max(abs(x) for x in deltas);flips=sum(s['threshold_flip'] for s in saved.values());checks['reported_aggregate_matches']=abs(maxdelta-a['groups']['all|all']['max_absolute_score_delta'])<1e-12 and flips==a['groups']['all|all']['threshold_flips'];result={'passed':all(checks.values()),'checks':checks,'threshold_flips':flips,'max_absolute_score_delta':maxdelta,'fixed_threshold':threshold,'source_model_sha256':hashlib.sha256(model.read_bytes()).hexdigest(),'scope':'Purposive12-prompt focus plus84 context prompts,132 repeats. No population inference, threshold retuning or numerical-identity repair. Score differences did not cross this fixed source threshold in this sample; the threshold itself is below0.01 and should not be treated as a probability calibration claim.'};(H/'independent_exp2_layout_transfer_review.json').write_text(json.dumps(result,indent=2)+'\n');print(json.dumps(result,indent=2));assert result['passed']
